html:
{#-
  Print Format : Change of Employment Details
  DocType      : Employee Record Update Request
  Type         : Jinja (custom_format = 1)
  Layout       : 1:1 with "CHANGE OF EMPLOYMENT DETAILS.docx"
                 Arial 10pt, line spacing 1.15, empty lines reproduced as .gap,
                 employee block double spaced, intro paragraph 1.5 spaced,
                 table = 3 equal columns, grey (#cccccc) bold centred header.
-#}
<style>
  .coed { font-family: Arial, Helvetica, sans-serif; font-size: 10pt; line-height: 1.15; color: #000; }
  .coed p { margin: 0; }
  .coed .gap { height: 0.65em; }
  .coed .sign-space { height: 45px; }
  .coed .emp-sign-space { height: 35px; }
  .coed p.sig-date { margin: 0 !important; padding: 0 !important; line-height: 1.9 !important; }
  .coed .letter-head img { max-height: 60px; width: auto !important; }
  .coed .dbl { line-height: 2; }
  .coed .one-half { line-height: 1.5; }
  .coed .center { text-align: center; }
  .coed table.terms { width: 100%; border-collapse: collapse; table-layout: fixed; margin: 0; }
  .coed table.terms col.c-terms, .coed table.terms col.c-current, .coed table.terms col.c-new { width: 33.33%; }
  .coed table, .coed th, .coed td { font-size: 10pt; }
  .coed table.terms th, .coed table.terms td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; line-height: 1.4; }
  .coed table.terms th { background: #cccccc !important; font-weight: bold; text-align: center; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .coed .sal-line { margin-bottom: 2px; }
  .coed .b-label { display: inline-block; min-width: 105px; }
</style>

{#- ---------- helpers ---------- -#}
{%- macro kd(v) -%}{{ "%.3f"|format(frappe.utils.flt(v)) }}/-{%- endmacro -%}

{%- set hr_user = frappe.db.get_single_value("HR Settings", "custom_hr_manager") -%}
{%- set hr = frappe.db.get_value("Employee", {"user_id": hr_user}, ["employee_name", "designation"], as_dict=1) if hr_user else None -%}

{%- set terms_rows = doc.get("employment_terms") or doc.get("properties") or [] -%}
{%- set show_terms = (doc.get("term_changes_required") or doc.get("properties_changes_required")) and terms_rows -%}
{%- set show_dayoff = doc.get("day_off_terms_required") -%}
{%- set show_salary = doc.get("salary_update_required") -%}
{%- set show_benefits = doc.get("benefits_changes_required") and doc.get("benefit") -%}

<div class="coed">

  {#- ONE FM letter head -#}
  {%- set lh_html = frappe.db.get_value("Letter Head", "ONEFM", "content") -%}
  {%- set logo_src = pow_logo_src() -%}
  <div class="letter-head">{% if logo_src %}<img src="{{ logo_src }}" alt="ONE FM">{% else %}{{ lh_html or "" }}{% endif %}</div>
  <div class="gap"></div>

  <p class="dbl"><b>Employee ID:</b> {{ doc.employee }}</p>
  <p class="dbl"><b>Employee Name:</b> {{ doc.employee_name }}</p>
  <p class="dbl"><b>Designation:</b> {{ doc.designation or "" }}</p>
  <p class="dbl"><b>Project:</b> {{ doc.project_allocation or "" }}</p>
  <div class="gap"></div>
  <p><b>Date</b>: {{ frappe.utils.formatdate(doc.creation, "dd-MM-yyyy") }}</p>
  <div class="gap"></div>
  <p class="center"><b>CHANGE OF EMPLOYMENT DETAILS</b></p>
  <div class="gap"></div>

  {%- set salutation = (frappe.db.get_value("Employee", doc.employee, "salutation") or "").strip() -%}
  {%- if salutation and not salutation.endswith(".") and salutation in ["Mr", "Mrs", "Ms", "Dr", "Prof", "Mx"] -%}{%- set salutation = salutation ~ "." -%}{%- endif -%}
  <p><b>Dear {{ (salutation ~ " ") if salutation else "" }}{{ doc.employee_name }},</b></p>
  <div class="gap"></div>
  <p class="one-half">We are pleased to inform you that you have below <b>Changes in your Employment Terms</b>, effective
     <b>{{ frappe.utils.formatdate(doc.effective_date_of_change, "dd-MM-yyyy") }}</b> in recognition of your
     performance and contribution to <b>One Facilities Management.</b></p>
  <div class="gap"></div>
  <div class="gap"></div>

  {% if show_terms or show_dayoff or show_salary %}
  <table class="terms">
    <colgroup><col class="c-terms"><col class="c-current"><col class="c-new"></colgroup>
    <tr><th>Terms</th><th>Current Details</th><th>New Details</th></tr>
    {% for row in terms_rows if show_terms %}
    <tr>
      <td>{{ row.get("terms") or row.get("property") }}</td>
      <td>{{ row.old_value or "" }}</td>
      <td>
        {%- if row.new_value_doctype == "Employee" -%}
          {{ row.new_value }} - {{ frappe.db.get_value("Employee", row.new_value, "employee_name") }}
        {%- else -%}{{ row.new_value or "" }}{%- endif -%}
      </td>
    </tr>
    {% endfor %}
    {% if show_dayoff %}
    <tr><td>Day Off Category</td><td>{{ doc.day_off_category_current_value or "" }}</td><td>{{ doc.day_off_category_new_value or "" }}</td></tr>
    <tr><td>Number of Days Off</td><td>{{ doc.number_of_days_off_current_value or "" }}</td><td>{{ doc.number_of_days_off_new_value or "" }}</td></tr>
    {% endif %}
    {% if show_salary %}
    {#- Base Salary row, then Salary Terms row -#}
    <tr class="base-row"><td>Base Salary</td><td>{{ kd(doc.current_base_salary) }} KD</td><td>{{ kd(doc.base_new_value) }} KD</td></tr>
    {#- Salary Terms: ALL components in ONE cell, one line each (as in reference image 2) -#}
    <tr>
      <td>Salary Terms</td>
      <td>
        {% for c in doc.salary_structure_components if frappe.utils.flt(c.amount) %}
          <div class="sal-line">{{ c.salary_component }}: {{ kd(c.amount) }}</div>
        {% endfor %}
      </td>
      <td>
        {#- New split = new Base Salary x component formula of the NEW Salary Structure (e.g. base*0.7) -#}
        {% if doc.salary_new_value %}
        {% for e in frappe.get_all("Salary Detail", filters={"parenttype": "Salary Structure", "parentfield": "earnings", "parent": doc.salary_new_value}, fields=["salary_component", "amount_based_on_formula", "formula", "amount"], order_by="idx asc") %}
          {%- set f = (e.formula or "").replace(" ", "") -%}
          {%- if e.amount_based_on_formula and f.startswith("base*") -%}
            {%- set expr = f[5:] -%}
            {%- if "/" in expr -%}{%- set parts = expr.split("/") -%}{%- set factor = frappe.utils.flt(parts[0]) / (frappe.utils.flt(parts[1]) or 1) -%}
            {%- else -%}{%- set factor = frappe.utils.flt(expr) -%}{%- endif -%}
            {%- set amt = frappe.utils.flt(doc.base_new_value) * factor -%}
          {%- else -%}{%- set amt = frappe.utils.flt(e.amount) -%}{%- endif -%}
          {% if amt %}<div class="sal-line">{{ e.salary_component }}: {{ kd(amt) }}</div>{% endif %}
        {% endfor %}
        {% endif %}
      </td>
    </tr>
    {% endif %}
  </table>
  {% endif %}

  <div class="gap"></div>

  {% if show_benefits %}
  <p><b>Additional Benefits:</b></p>
  <div class="gap"></div>
  {% for b in doc.benefit %}
  <p><span class="b-label">{{ b.get("terms") or b.get("property") }}</span> : {{ b.description or "" }}</p>
  <div class="gap"></div>
  {% endfor %}
  {% endif %}

  <p>All other terms and conditions of your employment remain unchanged.</p>
  <div class="gap"></div>
  <p>We wish you continued success in your new role.</p>
  <div class="gap"></div>
  <div class="gap"></div>
  <p>Sincerely,</p>
  <div class="sign-space"></div>
  <p>{{ hr.employee_name if hr else "" }}</p>
  <p>{{ hr.designation if hr else "" }}</p>
  <div class="gap"></div>
  <p><b>Employee Acknowledgement:</b></p>
  <div class="gap"></div>
  <p>I <b>{{ doc.employee_name }}</b> acknowledge the Changes made to my Employment Terms at <b>One Facilities Management</b>.</p>
  <div class="emp-sign-space"></div>
  <p class="sig-date"><b>Employee Signature:</b><br><b>Date:</b></p>
</div>
